create table public.order_addresses (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, kind text not null check(kind in ('shipping','billing')), recipient_name text not null, phone text, address_line1 text not null, address_line2 text, locality text not null, city text not null, region text not null, postal_code text not null, country_code char(2) not null, created_at timestamptz not null default now(), foreign key(store_id,order_id) references public.orders(store_id,id) on delete cascade, unique(order_id,kind));
